-- GENERATED by `cargo xtask legacy-import` from metrics/registry.toml and
-- ci/db/migrate-from-go/go-aggregate-views.toml. DO NOT EDIT.
--
-- `cargo xtask legacy-import --check` regenerates into a temporary directory and
-- diffs, so a hand edit here is a build failure rather than a surviving change.
-- The procedure these files implement is docs/data-migration.md.

-- The raw import. Runs on the TARGET.
--
-- The column list is computed at run time from w9.source_column INTERSECT
-- w9.expected_column rather than baked in, because production's width is unknown
-- (OQ-6) and a baked list would either fail on a missing column or silently skip a
-- present one. The emitted statements are a matched pair of COPYs, so 19 GB streams
-- through a pipe with no intermediate dump and no staging table:
--
--   psql "$SOURCE" -c "$(copy_out_sql ...)" | psql "$TARGET" -c "$(copy_in_sql)"
--
-- FORMAT csv, not binary. Binary COPY is faster and is only safe when both ends
-- run the same PostgreSQL major version, which is exactly what OQ-1 has not
-- established. CSV round-trips float4 exactly on PostgreSQL 12 and later, where the
-- default float output is shortest-exact.

-- The columns to move, in the destination's attribute order so that the two COPY
-- statements cannot disagree.
CREATE FUNCTION w9.import_columns() RETURNS text[]
LANGUAGE sql STABLE AS $fn$
    SELECT coalesce(array_agg(e.column_name ORDER BY e.ord), '{}'::text[])
      FROM w9.expected_column e
      JOIN w9.source_column  s USING (column_name)
$fn$;

-- stationname -> station_id as a CASE, so that the source side needs no join and
-- no temporary object. Three or four stations; this is a few hundred bytes.
CREATE FUNCTION w9.station_id_expr() RETURNS text
LANGUAGE plpgsql STABLE AS $fn$
DECLARE e text;
BEGIN
    SELECT 'CASE ' || string_agg(format('WHEN stationname = %L THEN %L',
                                        stationname, station_id), ' '
                                 ORDER BY stationname) || ' END'
      INTO e FROM w9.station_map;
    IF e IS NULL THEN
        RAISE EXCEPTION 'w9.station_map is empty; nothing can be assigned a station_id';
    END IF;
    RETURN e;
END $fn$;

-- One slice of the source, as a read-only statement to run on the OLD database.
-- Sliced because a 19 GB single COPY is not resumable and a failed one has to be
-- started again; sliced by time because that is how the chunks are laid out.
CREATE FUNCTION w9.copy_out_sql(t0 timestamptz, t1 timestamptz) RETURNS text
LANGUAGE sql STABLE AS $fn$
    SELECT format(
        'COPY (SELECT %s AS station_id, %s FROM weather '
        'WHERE time >= %L AND time < %L) TO STDOUT (FORMAT csv)',
        w9.station_id_expr(),
        (SELECT string_agg(quote_ident(c), ', ') FROM unnest(w9.import_columns()) c),
        t0, t1)
$fn$;

CREATE FUNCTION w9.copy_in_sql() RETURNS text
LANGUAGE sql STABLE AS $fn$
    SELECT format('COPY observations (station_id, %s) FROM STDIN (FORMAT csv)',
                  (SELECT string_agg(quote_ident(c), ', ')
                     FROM unnest(w9.import_columns()) c))
$fn$;

-- The slice boundaries, from the source's own extent. Seven days to match the
-- source's chunk interval, so a slice is one chunk's worth of sequential read.
CREATE TABLE w9.import_slice (
    t0        timestamptz PRIMARY KEY,
    t1        timestamptz NOT NULL,
    rows      bigint,
    done_at   timestamptz
);

-- Clear a slice before importing it. A slice that is planned and not marked done
-- either has never been imported or was interrupted part-way, and the second case
-- is the one that matters: COPY has no ON CONFLICT, so retrying a half-imported
-- slice fails on the first duplicate against
-- observations_station_id_time_key — which is exactly the unique index W4
-- assumption 34 asks to exist before the import, so the collision is a feature.
-- Deleting the slice's range first makes every slice retryable, and the ranges are
-- disjoint by construction so this can only remove that slice's own debris.
--
-- The alternative is a staging table per slice plus INSERT ... ON CONFLICT DO
-- NOTHING, which costs a second write of every row to avoid a DELETE that normally
-- removes nothing. Not worth it during an import that owns the table.
-- The parameters are named from_ts/to_ts, not t0/t1: w9.import_slice has columns
-- called t0 and t1, and plpgsql resolves the variable in preference to the column
-- without saying so.
CREATE PROCEDURE w9.reset_slice(from_ts timestamptz, to_ts timestamptz)
LANGUAGE plpgsql AS $fn$
DECLARE n bigint;
BEGIN
    IF EXISTS (SELECT 1 FROM w9.import_slice s
                WHERE s.t0 = from_ts AND s.done_at IS NOT NULL) THEN
        RAISE EXCEPTION 'slice % is already marked done; refusing to delete it', from_ts
            USING HINT = 'clear done_at first if the slice really has to be re-imported';
    END IF;
    DELETE FROM observations WHERE time >= from_ts AND time < to_ts;
    GET DIAGNOSTICS n = ROW_COUNT;
    IF n > 0 THEN
        RAISE NOTICE 'slice % had % rows from an interrupted attempt; removed', from_ts, n;
    END IF;
END $fn$;

CREATE PROCEDURE w9.plan_import(from_ts timestamptz, to_ts timestamptz,
                             slice interval DEFAULT INTERVAL '7 days')
LANGUAGE sql AS $fn$
    SELECT g, least(g + slice, to_ts)
      FROM generate_series(from_ts, to_ts - INTERVAL '1 microsecond', slice) g
    ON CONFLICT (t0) DO NOTHING;
$fn$;

-- ------------------------------------------------------------------
-- `stations` first. W4 2.1 makes it the reading-side projection every /span join
-- goes through, and the low-volume tables carry a foreign key to it, so a reading
-- whose station has no row is addressable by nothing.
-- ------------------------------------------------------------------

CREATE PROCEDURE w9.populate_stations() LANGUAGE plpgsql AS $fn$
BEGIN
    PERFORM w9.assert_station_map_complete();
                          altitude_ft, snow_base_distance_mm, first_seen, last_seen)
    SELECT m.station_id,
           m.stationname,
           coalesce(m.stationtype, s.stationtype, 'unknown'),
           m.timezone, m.latitude, m.longitude, m.altitude_ft,
           m.snow_base_distance_mm,
           coalesce(s.first_seen, now()), s.last_seen
      FROM w9.station_map m
      LEFT JOIN w9.source_station s USING (stationname)
    ON CONFLICT (station_id) DO UPDATE
       SET first_seen = least(stations.first_seen, excluded.first_seen),
           last_seen  = greatest(stations.last_seen, excluded.last_seen);
END $fn$;

-- `station_metrics` after the import: which metrics a station has ever reported
-- (W4 2.2). One sequential pass over the imported history, which is the scan the
-- Go TODO at internal/weatherstations/grpcreceiver/station.go:64 never wanted to
-- pay per request — paying it once, here, is what the table is for.
CREATE PROCEDURE w9.populate_station_metrics() LANGUAGE plpgsql AS $fn$
DECLARE r record; q text;
BEGIN
    FOR r IN SELECT e.column_name, m.key
               FROM w9.expected_column e
               JOIN w9.source_column USING (column_name)
               JOIN w9.metric_key m ON m.column_name = e.column_name
              WHERE e.kind = 'metric'
    LOOP
        q := format($q$
            SELECT station_id, %L, min(time), max(time)
              FROM observations WHERE %I IS NOT NULL GROUP BY 1
            ON CONFLICT (station_id, metric_key) DO UPDATE
               SET first_seen = least(station_metrics.first_seen, excluded.first_seen),
                   last_seen  = greatest(station_metrics.last_seen, excluded.last_seen)
        $q$, r.key, r.column_name);
        EXECUTE q;
    END LOOP;
END $fn$;

-- `station_metrics` is keyed by the registry's stable `key`, not by the column name
-- (W4 2.2): `out_temp` is what the API calls the metric and `outtemp` is an
-- artefact of what the old database happened to name a column.
CREATE TABLE w9.metric_key (column_name text PRIMARY KEY, key text NOT NULL);
